<section class="roster">
  <header class="roster__header">
    <h1 class="roster__title">Roster</h1>
    <a hlmBtn routerLink="/recruit" class="roster__recruit">
      <ng-icon name="lucideUserPlus" aria-hidden="true" />
      Recruit
    </a>
  </header>

  <section hlmCard class="roster__panel" aria-label="Hero roster">
    <div hlmCardHeader class="roster__filters" role="search">
      <label hlmLabel for="roster-search" class="roster__label">Search heroes</label>
      <input
        #search
        hlmInput
        id="roster-search"
        type="search"
        class="roster__search"
        placeholder="Name, alias or ID"
        [value]="vm.query()"
        (input)="vm.setQuery(search.value)"
      />

      <label hlmLabel for="roster-class" class="roster__label">Power class</label>
      <hlm-select [itemToString]="vm.classLabel" [value]="vm.classFilter()" (valueChange)="vm.setClassFilter($event)">
        <hlm-select-trigger buttonId="roster-class" class="roster__class">
          <hlm-select-value />
        </hlm-select-trigger>
        <hlm-select-content *hlmSelectPortal>
          @for (option of vm.classOptions; track option) {
            <hlm-select-item [value]="option">{{ vm.classLabel(option) }}</hlm-select-item>
          }
        </hlm-select-content>
      </hlm-select>
    </div>

    <div hlmCardContent class="roster__content">
      <div hlmTableContainer>
        <table hlmTable aria-label="Heroes, sorted by power">
          <thead hlmTableHeader>
            <tr hlmTableRow>
              <th hlmTableHead>Hero</th>
              <th hlmTableHead>Class</th>
              <th hlmTableHead class="roster__num">Power</th>
              <th hlmTableHead>Status</th>
              <th hlmTableHead>Clearance</th>
              <th hlmTableHead>Actions</th>
            </tr>
          </thead>
          <tbody hlmTableBody>
            @for (row of vm.rows(); track row.hero.id) {
              <tr hlmTableRow>
                <td hlmTableCell>
                  <div class="roster__hero">
                    <hlm-avatar size="sm">
                      <span hlmAvatarFallback>{{ row.initials }}</span>
                    </hlm-avatar>
                    <div class="roster__identity">
                      <a class="roster__name" [routerLink]="['/detail', row.hero.id]">{{ row.hero.name }}</a>
                      <span class="roster__id">{{ row.hero.id }}</span>
                    </div>
                  </div>
                </td>
                <td hlmTableCell>
                  <hlm-badge variant="outline">{{ row.hero.powerClass }}</hlm-badge>
                </td>
                <td hlmTableCell class="roster__num roster__power">{{ row.hero.powerIndex }}</td>
                <td hlmTableCell>
                  <hlm-badge [variant]="row.statusVariant">{{ row.hero.status }}</hlm-badge>
                </td>
                <td hlmTableCell>{{ row.hero.clearance }}</td>
                <td hlmTableCell>
                  <a
                    hlmBtn
                    variant="ghost"
                    size="icon"
                    [routerLink]="['/detail', row.hero.id]"
                    [attr.aria-label]="'Edit ' + row.hero.name"
                    hlmTooltip="Edit hero"
                  >
                    <ng-icon name="lucidePencil" aria-hidden="true" />
                  </a>
                </td>
              </tr>
            } @empty {
              <tr hlmTableRow>
                <td hlmTableCell colspan="6" class="roster__empty">No heroes match these filters.</td>
              </tr>
            }
          </tbody>
        </table>
      </div>
    </div>

    <div hlmCardFooter class="roster__footer">
      <p class="roster__count">{{ vm.shownCount() }} of {{ vm.totalCount() }} heroes</p>
      <p class="roster__sort">Sorted by power</p>
    </div>
  </section>
</section>
