---
@reference "../../styles.css";

.roster {
  @apply flex min-w-0 flex-col gap-6;
}

.roster__header {
  @apply flex flex-wrap items-center justify-between gap-3;
}

.roster__title {
  @apply text-2xl font-semibold;
}

.roster__panel {
  @apply min-w-0;
}

/* Below sm the filters stack; the search and class filter each take a full row. */
.roster__filters {
  @apply flex flex-wrap items-center gap-3;
}

.roster__label {
  @apply sr-only;
}

.roster__search {
  @apply w-full sm:w-64;
}

.roster__class {
  @apply w-full sm:w-48;
}

/* The table scrolls inside its own container (hlmTableContainer), so the page never does. */
.roster__content {
  @apply min-w-0;
}

.roster__hero {
  @apply flex items-center gap-3;
}

.roster__identity {
  @apply flex min-w-0 flex-col;
}

.roster__name {
  @apply font-medium hover:underline;
}

.roster__id {
  @apply text-xs text-muted-foreground;
}

.roster__num {
  @apply text-end;
}

.roster__power {
  @apply font-semibold tabular-nums;
}

.roster__empty {
  @apply py-8 text-center text-muted-foreground;
}

.roster__footer {
  @apply flex flex-wrap items-center justify-between gap-2 text-sm text-muted-foreground;
}

.roster__count {
  @apply font-medium text-foreground;
}
---
@reference "../../styles.css";

.dashboard {
  @apply flex min-w-0 flex-col gap-8;
}

.dashboard__header {
  @apply flex flex-wrap items-center justify-between gap-3;
}

.dashboard__title {
  @apply text-2xl font-semibold;
}

.dashboard__primary {
  @apply ms-auto;
}

.dashboard__stats {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4;
}

.dashboard__stat-icon {
  @apply size-5 shrink-0 text-muted-foreground;
}

.dashboard__section {
  @apply flex min-w-0 flex-col gap-4;
}

.dashboard__section-header {
  @apply flex flex-wrap items-center justify-between gap-3;
}

.dashboard__section-title {
  @apply text-lg font-semibold;
}

.dashboard__hero-grid {
  @apply grid grid-cols-[repeat(auto-fill,minmax(min(100%,14.5rem),1fr))] gap-4;
}

