1	import { computed, inject, Injectable } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { NavigationEnd, Router } from '@angular/router';
4	import { filter, map } from 'rxjs';
5	import { ThemeService } from './theme.service';
6	
7	export interface NavItem {
8	  readonly label: string;
9	  readonly path: string;
10	  readonly icon: string;
11	}
12	
13	export interface Crumb {
14	  readonly label: string;
15	  readonly path?: string;
16	}
17	
18	// The six rail destinations. Hero detail is reached from the roster, not the rail.
19	const NAV_ITEMS: readonly NavItem[] = [
20	  { label: 'Dashboard', path: '/dashboard', icon: 'lucideLayoutDashboard' },
21	  { label: 'Roster', path: '/roster', icon: 'lucideUsers' },
22	  { label: 'Missions', path: '/missions', icon: 'lucideTarget' },
23	  { label: 'Threats', path: '/threats', icon: 'lucideShieldAlert' },
24	  { label: 'Recruit', path: '/recruit', icon: 'lucideUserPlus' },
25	  { label: 'Settings', path: '/settings', icon: 'lucideSettings' },
26	];
27	
28	const SECTION_LABELS: Readonly<Record<string, string>> = {
29	  dashboard: 'Dashboard',
30	  roster: 'Roster',
31	  detail: 'Hero Detail',
32	  missions: 'Missions',
33	  threats: 'Threats',
34	  recruit: 'Recruit',
35	  settings: 'Settings',
36	};
37	
38	@Injectable()
39	export class AppShellViewModel {
40	  private readonly router = inject(Router);
41	  private readonly theme = inject(ThemeService);
42	
43	  private readonly url = toSignal(
44	    this.router.events.pipe(
45	      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
46	      map((event) => event.urlAfterRedirects),
47	    ),
48	    { initialValue: this.router.url },
49	  );
50	
51	  readonly nav = NAV_ITEMS;
52	
53	  readonly darkMode = this.theme.dark;
54	
55	  readonly crumbs = computed<readonly Crumb[]>(() => {
56	    const section = this.url().split(/[/?#]/).filter(Boolean)[0] ?? 'dashboard';
57	    const parent: readonly Crumb[] = section === 'detail' ? [{ label: 'Roster', path: '/roster' }] : [];
58	    return [{ label: 'Hero Ops', path: '/dashboard' }, ...parent, { label: SECTION_LABELS[section] ?? 'Dashboard' }];
59	  });
60	
61	  toggleTheme(): void {
62	    this.theme.toggle();
63	  }
64	}
