.detail__stats {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-3;
}

.detail__stat-icon {
  @apply size-5 shrink-0 text-muted-foreground;
}

.detail__columns {
  @apply grid grid-cols-1 gap-6 lg:grid-cols-2;
}

.detail__card {
  @apply min-w-0;
}

.detail__notes {
  @apply text-sm;
}

.detail__facts {
  @apply grid grid-cols-1 gap-3 sm:grid-cols-2;
}

.detail__fact {
  @apply flex min-w-0 flex-col gap-0.5;
}

.detail__term {
  @apply text-xs text-muted-foreground;
}

.detail__value {
  @apply text-sm font-medium break-words;
}

.detail__form {
  @apply flex flex-col gap-6;
}

/* The schema form is one column on a phone and two from sm; notes spans both. */
.detail__fields {
  @apply grid grid-cols-1 gap-4 sm:grid-cols-2;
}

.detail__wide {
  @apply sm:col-span-2;
}

.detail__select {
  @apply w-full;
}

.detail__form-actions {
  @apply flex flex-wrap items-center justify-end gap-2;
}

.detail__saved {
  @apply me-auto text-sm text-muted-foreground;
}
